create extension if not exists "pgcrypto";
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null default 'Side-quester', avatar_url text, created_at timestamptz not null default now());
create table public.groups (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 2 and 50), emoji text not null default '✌️', created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.group_members (group_id uuid references public.groups on delete cascade, user_id uuid references public.profiles on delete cascade, role text not null default 'member' check(role in ('owner','member')), joined_at timestamptz not null default now(), primary key(group_id,user_id));
create table public.quests (id uuid primary key default gen_random_uuid(), group_id uuid references public.groups on delete cascade, title text not null, prompt text not null, minutes smallint not null check(minutes between 5 and 120), setting text not null check(setting in ('indoors','outdoors','anywhere')), people text not null default 'any', cost_cents integer not null default 0 check(cost_cents >= 0), active boolean not null default true, created_at timestamptz not null default now());
create table public.memories (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups on delete cascade, quest_id uuid references public.quests on delete set null, author_id uuid not null references public.profiles(id), caption text not null check(char_length(caption) between 1 and 220), image_path text not null, created_at timestamptz not null default now());
create table public.memory_votes (memory_id uuid references public.memories on delete cascade, user_id uuid references public.profiles on delete cascade, created_at timestamptz not null default now(), primary key(memory_id,user_id));
alter table public.profiles enable row level security; alter table public.groups enable row level security; alter table public.group_members enable row level security; alter table public.quests enable row level security; alter table public.memories enable row level security; alter table public.memory_votes enable row level security;
create function public.is_member(target_group uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.group_members where group_id=target_group and user_id=auth.uid())$$;
create policy "members read groups" on public.groups for select using (public.is_member(id));
create policy "members read membership" on public.group_members for select using (public.is_member(group_id));
create policy "members read quests" on public.quests for select using (group_id is null or public.is_member(group_id));
create policy "members read memories" on public.memories for select using (public.is_member(group_id));
create policy "members add memories" on public.memories for insert with check (author_id=auth.uid() and public.is_member(group_id));
create policy "members read votes" on public.memory_votes for select using (exists(select 1 from public.memories m where m.id=memory_id and public.is_member(m.group_id)));
create policy "members vote" on public.memory_votes for insert with check (user_id=auth.uid() and exists(select 1 from public.memories m where m.id=memory_id and public.is_member(m.group_id)));
create policy "members remove own vote" on public.memory_votes for delete using (user_id=auth.uid());
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,display_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name','Side-quester'),new.raw_user_meta_data->>'avatar_url'); return new; end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into storage.buckets(id,name,public) values ('memory-photos','memory-photos',false) on conflict do nothing;
create policy "members upload proof" on storage.objects for insert to authenticated with check (bucket_id='memory-photos' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "users read group proof" on storage.objects for select to authenticated using (bucket_id='memory-photos');
